<script setup lang="ts">
import type {DecorationBlock,DecorationLink} from '../../../../api/src/core/decoration-types'
import {decorationOptions,visibleDecorationItems} from '../../../../api/src/core/decoration-options.mjs'
import {frameworkAsset,decorationIcons} from '../../../../api/src/core/decoration-framework.mjs'
const props=defineProps<{block:DecorationBlock;editable?:boolean;imageUrl:(id:string)=>string}>()
const emit=defineEmits<{navigate:[target:DecorationLink]}>()
const o=computed(()=>decorationOptions(props.block)),items=computed(()=>visibleDecorationItems(props.block))
const icon=(name:string|undefined,blue=false)=>frameworkAsset('icons/'+(decorationIcons.includes(name||'')?name:'layout-grid')+(blue?'-blue':'')+'.svg')
function go(target:DecorationLink){if(!props.editable&&target)emit('navigate',target)}
</script>
<template><section v-if="block.type==='intro'" class="framework-intro" :style="{backgroundImage:'url('+(block.imageId?imageUrl(block.imageId):frameworkAsset('intro.webp'))+')'}"><p class="intro-eyebrow">{{o.eyebrow}}</p><h2>{{block.title}}</h2><p class="intro-description">{{block.text}}</p><button class="intro-action" type="button" @click="go(block.target)">{{o.buttonText}}<img :src="icon('arrow-right',true)" alt=""></button></section>
<section v-else-if="block.type==='features'" class="framework-features"><h2 v-if="block.title">{{block.title}}</h2><div class="features-grid"><button v-for="item in items" :key="item.id" type="button" :disabled="!item.target" @click="go(item.target)"><span class="feature-icon"><img :src="item.imageId?imageUrl(item.imageId):icon(item.icon,true)" alt=""></span><strong>{{item.label}}</strong><span v-if="item.text" class="feature-description">{{item.text}}</span></button></div><p v-if="block.text" class="features-footer">{{block.text}}</p></section>
<section v-else-if="block.type==='orders'" class="framework-orders"><header><h2>{{block.title}}</h2><button v-if="block.target" type="button" class="section-more" :disabled="editable" @click="go(block.target)">全部订单<img :src="icon('chevron-right')" alt=""></button><span v-else-if="editable" class="order-setup">请选择订单入口</span></header><div v-if="items.length" class="order-shortcuts" :style="{gridTemplateColumns:'repeat('+Math.min(items.length,4)+',minmax(0,1fr))'}"><button v-for="item in items" :key="item.id" type="button" :disabled="editable||!item.target" @click="go(item.target)"><span class="order-shortcut-icon"><img :src="item.imageId?imageUrl(item.imageId):icon(item.icon,true)" alt=""></span><span>{{item.label}}</span></button></div></section>
</template>
